import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { mockEquipments } from '../data/mockEquipments';
import EquipmentCard from '../components/EquipmentCard';

export default function Home() {
  const navigate = useNavigate();
  const [heroSearch, setHeroSearch] = useState('');

  const handleHeroSearchSubmit = (e) => {
    e.preventDefault();
    if (heroSearch.trim()) {
      navigate(`/equipments?search=${encodeURIComponent(heroSearch)}`);
    } else {
      navigate('/equipments');
    }
  };

  const quickCategories = [
    { name: '📷 อุปกรณ์ถ่ายภาพ', category: 'อุปกรณ์ถ่ายภาพ' },
    { name: '💻 ไอที & โน้ตบุ๊ก', category: 'ไอที' },
    { name: '⚽ อุปกรณ์กีฬา', category: 'กีฬา' },
    { name: '🎸 อื่นๆ', category: 'อื่นๆ' }
  ];

  const popularEquipments = mockEquipments.slice(0, 4);

